  json.bufferViews = json.bufferViews.map((view) =>
    append(binary.subarray(view.byteOffset ?? 0, (view.byteOffset ?? 0) + view.byteLength), view),
  );
  const widths = { scalar: 1, vec2: 2, vec3: 3, vec4: 4 };
  const bytes = { 5120: 1, 5121: 1, 5122: 2, 5123: 2, 5125: 4, 5126: 4 };
  for (const accessor of json.accessors) {
    const view = json.bufferViews[accessor.bufferView];
    const held = Math.floor(
      (view.byteLength - (accessor.byteOffset ?? 0)) /
        (view.byteStride ?? widths[accessor.type.toLowerCase()] * bytes[accessor.componentType]),
    );
    accessor.count = Math.min(accessor.count, held);
    if (!(accessor.count > 0)) throw new Error(`Empty accessor in ${source}`);
  }
